def compute_clean_accuracy(clean_scores, pairs, datasets=None, all_models=None):
    """Compute clean accuracy for each (model, dataset).

    Returns: {(model_id, ds): float}
    """
    datasets = datasets or DATASETS
    all_models = all_models or ALL_MODELS
    acc = {}
    for ds in datasets:
        ds_pairs = pairs.get(ds, [])
        for mid in all_models:
            if mid not in clean_scores.get(ds, {}):
                continue
            scores = clean_scores[ds][mid]
            n = min(len(scores), len(ds_pairs))
            if n == 0:
                continue
            n_correct = 0
            for i in range(n):
                gt = ds_pairs[i]["ground_truth_winner"]
                w = scores[i].get("winner") if isinstance(scores[i], dict) else None
                if w == gt:
                    n_correct += 1
            acc[(mid, ds)] = n_correct / n
    return acc


def flag_low_accuracy_conditions(clean_scores, pairs, threshold=0.5,
                                  datasets=None, all_models=None):
    """Flag (model, dataset) combos where clean accuracy < threshold.

    Returns: set of (model_id, dataset)
    """
    acc = compute_clean_accuracy(clean_scores, pairs, datasets, all_models)
    flagged = set()
    for (mid, ds), a in acc.items():
        if a < threshold:
            logger.warning(f"Low clean accuracy: {mid} on {ds} = {a:.3f} < {threshold}")
            flagged.add((mid, ds))
    return flagged
